import { afterEach, beforeEach, describe, expect, it, vi } from 'vitest';
import { fromPartial } from '@total-typescript/shoehorn';
import type { Bindings } from '../env';
import { matchSourceControlTreeBlobs } from '../source-control';
import {
  lookupSnapshotCache,
  publishSnapshotCache,
  resolveCacheKey,
  type CacheKeyInput,
} from './cache';

describe('resolveCacheKey', () => {
  it.each([
    ['command', { command: 'bun run build:prod' }],
    ['cwd', { cwd: 'packages/app' }],
    ['env', { env: { NODE_ENV: 'production' } }],
  ])('changes when %s changes', async (_field, change) => {
    expect(await resolveCacheKey({ ...input, ...change })).not.toBe(
      await resolveCacheKey(input)
    );
  });

  it('is independent of env insertion order', async () => {
    const first = await resolveCacheKey({
      ...input,
      env: { NODE_ENV: 'production', REGION: 'eu' },
    });
    const second = await resolveCacheKey({
      ...input,
      env: { REGION: 'eu', NODE_ENV: 'production' },
    });

    expect(first).toBe(second);
  });
});

describe('matchSourceControlTreeBlobs', () => {
  const tree = [
    { path: 'index.ts', sha: 'root' },
    { path: 'src/index.ts', sha: 'nested' },
    { path: 'foo/bar.ts', sha: 'direct' },
    { path: 'foo/a/bar.ts', sha: 'deep' },
    { path: '?literal.ts', sha: 'literal' },
  ];

  it.each([
    [
      '**/*.ts',
      ['index.ts', 'src/index.ts', 'foo/bar.ts', 'foo/a/bar.ts', '?literal.ts'],
    ],
    ['foo/**/bar.ts', ['foo/bar.ts', 'foo/a/bar.ts']],
    ['src/*.ts', ['src/index.ts']],
    ['?literal.ts', ['?literal.ts']],
  ])('matches %s', (pattern, expected) => {
    expect(matchSourceControlTreeBlobs(tree, [pattern])).toEqual(
      tree.filter((entry) => expected.includes(entry.path))
    );
  });
});

describe('snapshot cache', () => {
  beforeEach(() => {
    vi.useFakeTimers();
    vi.setSystemTime(new Date('2026-07-31T00:00:00.000Z'));
  });

  afterEach(() => vi.useRealTimers());

  it('misses when no pointer exists', async () => {
    const bucket = fakeBucket();

    await expect(
      lookupSnapshotCache(bindings(bucket), { key: 'key-1', label: 'build' })
    ).resolves.toEqual({ status: 'miss' });
    expect(bucket.get).toHaveBeenCalledWith('cache/key-1.json');
    expect(bucket.head).not.toHaveBeenCalled();
  });

  it.each([
    { backupId: 123 },
    { ...cachePointer, backupId: 'not-a-uuid' },
    { ...cachePointer, dir: 'workspace' },
    { ...cachePointer, dir: '/workspace/../tmp' },
    { ...cachePointer, dir: '/workspace\0escape' },
  ])('misses when the pointer is malformed', async (pointer) => {
    const bucket = fakeBucket({ pointer });

    await expect(
      lookupSnapshotCache(bindings(bucket), { key: 'key-1', label: 'build' })
    ).resolves.toEqual({ status: 'miss' });
    expect(bucket.head).not.toHaveBeenCalled();
  });

  it('misses when pointer JSON cannot be decoded', async () => {
    const bucket = fakeBucket({ pointer: new SyntaxError('invalid JSON') });

    await expect(
      lookupSnapshotCache(bindings(bucket), { key: 'key-1', label: 'build' })
    ).resolves.toEqual({ status: 'miss' });
    expect(bucket.head).not.toHaveBeenCalled();
  });

  it('returns a snapshot when the pointer and backup are usable', async () => {
    const bucket = fakeBucket({ pointer: cachePointer });

    await expect(
      lookupSnapshotCache(bindings(bucket), { key: 'key-1', label: 'build' })
    ).resolves.toEqual({
      status: 'hit',
      snapshot: { id: backupId, dir: '/workspace' },
      cachePointer: {
        key: 'key-1',
        createdAt: '2026-07-30T00:00:00.000Z',
        sizeBytes: 123,
      },
    });
  });

  it('misses when the pointed-to backup is expired', async () => {
    const bucket = fakeBucket({
      pointer: cachePointer,
      metadata: { createdAt: '2026-07-01T00:00:00.000Z', ttl: 60 },
    });

    await expect(
      lookupSnapshotCache(bindings(bucket), { key: 'key-1', label: 'build' })
    ).resolves.toEqual({ status: 'miss' });
    expect(bucket.head).not.toHaveBeenCalled();
  });

  it('misses when backup metadata is malformed', async () => {
    const bucket = fakeBucket({
      pointer: cachePointer,
      metadata: { createdAt: '2026-07-30T00:00:00.000Z', ttl: 'forever' },
    });

    await expect(
      lookupSnapshotCache(bindings(bucket), { key: 'key-1', label: 'build' })
    ).resolves.toEqual({ status: 'miss' });
    expect(bucket.head).not.toHaveBeenCalled();
  });

  it('misses when backup metadata JSON cannot be decoded', async () => {
    const bucket = fakeBucket({
      pointer: cachePointer,
      metadata: new SyntaxError('invalid JSON'),
    });

    await expect(
      lookupSnapshotCache(bindings(bucket), { key: 'key-1', label: 'build' })
    ).resolves.toEqual({ status: 'miss' });
    expect(bucket.head).not.toHaveBeenCalled();
  });

  it('misses when backup expiry overflows', async () => {
    const bucket = fakeBucket({
      pointer: cachePointer,
      metadata: {
        createdAt: '2026-07-30T00:00:00.000Z',
        ttl: Number.MAX_VALUE,
      },
    });

    await expect(
      lookupSnapshotCache(bindings(bucket), { key: 'key-1', label: 'build' })
    ).resolves.toEqual({ status: 'miss' });
    expect(bucket.head).not.toHaveBeenCalled();
  });

  it('publishes a usable backup and returns its cache metadata', async () => {
    const bucket = fakeBucket();

    await expect(
      publishSnapshotCache(bindings(bucket), {
        key: 'key-1',
        label: 'build',
        snapshot: { id: backupId, dir: '/workspace' },
        producedBySha: 'commit-1',
      })
    ).resolves.toEqual({
      key: 'key-1',
      createdAt: '2026-07-30T00:00:00.000Z',
      sizeBytes: 123,
    });
    expect(bucket.put).toHaveBeenCalledWith(
      'cache/key-1.json',
      JSON.stringify({
        backupId,
        dir: '/workspace',
        producedBySha: 'commit-1',
        createdAt: '2026-07-30T00:00:00.000Z',
      })
    );
  });

  it('refuses to publish a backup outside the runner workspace', async () => {
    const bucket = fakeBucket();

    await expect(
      publishSnapshotCache(bindings(bucket), {
        key: 'key-1',
        label: 'build',
        snapshot: { id: backupId, dir: '/tmp' },
        producedBySha: 'commit-1',
      })
    ).rejects.toThrow('build produced a backup outside /workspace');
    expect(bucket.put).not.toHaveBeenCalled();
  });
});

function fakeBucket(options?: { pointer?: unknown; metadata?: unknown }) {
  const metadata =
    options && 'metadata' in options
      ? options.metadata
      : {
          createdAt: '2026-07-30T00:00:00.000Z',
          ttl: 30 * 24 * 60 * 60,
        };
  return {
    get: vi.fn().mockImplementation((key: string) => {
      if (key.startsWith('cache/')) {
        return Promise.resolve(
          options && 'pointer' in options
            ? { json: () => json(options.pointer) }
            : null
        );
      }
      return Promise.resolve({ json: () => json(metadata) });
    }),
    head: vi.fn().mockResolvedValue({ size: 123 }),
    put: vi.fn().mockResolvedValue(undefined),
  };
}

function json(value: unknown) {
  return value instanceof Error
    ? Promise.reject(value)
    : Promise.resolve(value);
}

function bindings(bucket: ReturnType<typeof fakeBucket>) {
  return fromPartial<Bindings>({ BACKUP_BUCKET: bucket });
}

const backupId = '123e4567-e89b-12d3-a456-426614174000';

const cachePointer = {
  backupId,
  dir: '/workspace',
  producedBySha: 'commit-1',
  createdAt: '2026-07-30T00:00:00.000Z',
};

const input = {
  repo: 'cloudflare-artifacts:cloudflare/example:refs/heads/main',
  label: 'build',
  command: 'bun run build',
  paths: ['bun.lock'],
  blobs: [{ path: 'bun.lock', sha: 'blob-sha' }],
} satisfies CacheKeyInput;

import { describe, expect, it, vi } from 'vitest';
import type { StepNotificationHandle } from '../source-control';
import {
  withStepNotification,
  type CompletedStepExecution,
  type StepExecution,
} from './step-notification';

describe('withStepNotification', () => {
  it('reports success and returns the runner output', async () => {
    const handle = notificationHandle();
    const execution = successfulExecution({ cacheHit: true });

    await expect(
      withStepNotification(
        notificationInput(handle),
        () => Promise.resolve(execution),
        passthrough
      )
    ).resolves.toEqual({
      exitCode: 0,
      logs: execution.logs,
      snapshot: execution.snapshot,
      cachePointer: undefined,
    });
    expect(handle.succeed).toHaveBeenCalledWith(
      expect.objectContaining({ cacheHit: true, command: 'pnpm test' })
    );
    expect(handle.fail).not.toHaveBeenCalled();
  });

  it('reports a successful execution without a snapshot as a failure', async () => {
    const handle = notificationHandle();

    await expect(
      withStepNotification(
        notificationInput(handle),
        () => Promise.resolve(successfulExecution({ snapshot: undefined })),
        passthrough
      )
    ).rejects.toThrow('test did not produce a workspace snapshot');
    expect(handle.succeed).not.toHaveBeenCalled();
    expect(handle.fail).toHaveBeenCalledOnce();
  });

  it('reports a rejected success notification as a step failure', async () => {
    const handle = notificationHandle();
    vi.mocked(handle.succeed).mockRejectedValue(new Error('completion failed'));

    await expect(
      withStepNotification(
        notificationInput(handle),
        () => Promise.resolve(successfulExecution()),
        passthrough
      )
    ).rejects.toThrow('completion failed');
    expect(handle.fail).toHaveBeenCalledOnce();
  });

  it('redacts diagnostics and cancels streamed logs on failure', async () => {
    const handle = notificationHandle();
    const cancel = vi.fn();
    const stdout = new ReadableStream<Uint8Array>({ cancel });
    const preview = {
      stdout: 'token=[REDACTED]',
      stderr: 'command failed',
    };

    const failure = withStepNotification(
      notificationInput(handle, ['super-secret']),
      () =>
        Promise.resolve({
          exitCode: 1,
          logs: { stdout, stderr: '' },
          preview,
          cacheHit: false,
        }),
      passthrough
    );

    await expect(failure).rejects.toThrow('token=[REDACTED]');
    expect(cancel).toHaveBeenCalledOnce();
    expect(handle.fail).toHaveBeenCalledOnce();
    expect(JSON.stringify(vi.mocked(handle.fail).mock.calls)).not.toContain(
      'super-secret'
    );
  });

  it('does not replace the step error when log cleanup fails', async () => {
    const handle = notificationHandle();
    const stdout = new ReadableStream<Uint8Array>({
      cancel: () => {
        throw new Error('cleanup failed');
      },
    });
    const consoleError = vi
      .spyOn(console, 'error')
      .mockImplementation(() => undefined);

    await expect(
      withStepNotification(
        notificationInput(handle),
        () =>
          Promise.resolve({
            exitCode: 1,
            logs: { stdout, stderr: '' },
            preview: { stdout: '', stderr: 'command failed' },
            cacheHit: false,
          }),
        passthrough
      )
    ).rejects.toThrow('test failed with exit code 1');
    expect(consoleError).toHaveBeenCalledWith(
      'Failed to cancel CI log streams',
      expect.anything()
    );
    expect(handle.fail).toHaveBeenCalledOnce();

    consoleError.mockRestore();
  });

  it('does not replace the step error when failure reporting fails', async () => {
    const handle = notificationHandle();
    vi.mocked(handle.fail).mockRejectedValue(new Error('notification failed'));
    const consoleError = vi
      .spyOn(console, 'error')
      .mockImplementation(() => undefined);

    await expect(
      withStepNotification(
        notificationInput(handle),
        () => Promise.reject(new Error('runner failed')),
        passthrough
      )
    ).rejects.toThrow('runner failed');
    expect(consoleError).toHaveBeenCalledWith(
      'Failed to report CI step failure',
      expect.anything()
    );

    consoleError.mockRestore();
  });
});

function passthrough(execution: CompletedStepExecution) {
  return Promise.resolve(execution);
}

function notificationHandle(): StepNotificationHandle {
  return {
    succeed: vi.fn().mockResolvedValue(undefined),
    fail: vi.fn().mockResolvedValue(undefined),
  };
}

function notificationInput(
  handle: StepNotificationHandle,
  sensitiveValues: string[] = []
) {
  return {
    handle,
    label: 'test',
    command: 'pnpm test',
    sensitiveValues,
  };
}

function successfulExecution(
  overrides: Partial<StepExecution> = {}
): StepExecution {
  return {
    exitCode: 0,
    logs: { stdout: 'ok', stderr: '' },
    preview: { stdout: 'ok', stderr: '' },
    snapshot: { id: 'backup-1', dir: '/workspace' },
    cacheHit: false,
    ...overrides,
  };
}

import { describe, expect, it, vi } from 'vitest';
import { fromPartial } from '@total-typescript/shoehorn';
import { restartCiRun, startCiRun } from './dispatch';
import { runId } from './run-id';
import type { Bindings } from '../env';
import type { CiParams, CloudflareArtifacts } from '../pipeline';

const params = {
  provider: 'cloudflare-artifacts',
  providerData: { namespace: 'ci-cd-worker' },
  event: { type: 'push' },
  owner: 'ci-cd-worker',
  repo: 'ci-workflows-demo',
  sha: 'abc123',
  remote: 'cloudflare',
  trigger: 'push',
  ref: 'refs/heads/main',
  branch: 'main',
} satisfies CiParams<CloudflareArtifacts>;

describe('static CI workflow dispatch', () => {
  it('starts the static workflow with the run id and source params', async () => {
    const id = await runId(params);
    const createBatch = vi.fn().mockResolvedValue([{ id }]);
    const env = workflowEnv({ createBatch });

    await expect(startCiRun(env, params)).resolves.toBe(id);
    expect(createBatch).toHaveBeenCalledWith([{ id, params }]);
  });

  it('deduplicates an existing commit run', async () => {
    const createBatch = vi.fn().mockResolvedValue([]);

    await expect(
      startCiRun(workflowEnv({ createBatch }), params)
    ).resolves.toBeNull();
  });

  it('restarts the static workflow instance', async () => {
    const id = await runId(params);
    const restart = vi.fn().mockResolvedValue(undefined);
    const get = vi.fn().mockResolvedValue({ id, restart });

    await expect(restartCiRun(workflowEnv({ get }), params)).resolves.toBe(id);
    expect(get).toHaveBeenCalledWith(id);
    expect(restart).toHaveBeenCalledOnce();
  });

  it('propagates workflow restart failures', async () => {
    const error = new Error('restart unavailable');
    const get = vi.fn().mockResolvedValue({
      id: await runId(params),
      restart: vi.fn().mockRejectedValue(error),
    });

    await expect(restartCiRun(workflowEnv({ get }), params)).rejects.toBe(
      error
    );
  });
});

function workflowEnv(workflow: {
  createBatch?: ReturnType<typeof vi.fn>;
  get?: ReturnType<typeof vi.fn>;
}) {
  return fromPartial<Bindings>({
    CI_WORKFLOW: fromPartial<Bindings['CI_WORKFLOW']>(workflow),
  });
}

import { afterEach, beforeEach, describe, expect, it, vi } from 'vitest';
import { fromPartial } from '@total-typescript/shoehorn';
import type { Bindings } from '../env';
import type { CiRunStepInput, CloudflareArtifacts } from '../pipeline';
import type { SourceControlProvider } from '../source-control';
import {
  cloudflareArtifacts,
  type SourceControlAdapter,
} from '../source-control-adapter';

const mocks = vi.hoisted(() => ({
  lookupSnapshotCache: vi.fn(),
  publishSnapshotCache: vi.fn(),
  resolveCacheKey: vi.fn(),
  run: vi.fn(),
}));

vi.mock('./runners/sandbox', () => ({
  SandboxRunner: class {
    run = mocks.run;
  },
}));

vi.mock('./cache', () => ({
  lookupSnapshotCache: mocks.lookupSnapshotCache,
  publishSnapshotCache: mocks.publishSnapshotCache,
  resolveCacheKey: mocks.resolveCacheKey,
}));

import { runCiStep } from './capabilities';

describe('runCiStep', () => {
  afterEach(() => vi.restoreAllMocks());

  beforeEach(() => {
    vi.clearAllMocks();
    mocks.lookupSnapshotCache.mockResolvedValue({ status: 'miss' });
    mocks.resolveCacheKey.mockResolvedValue('cache-key');
    mocks.publishSnapshotCache.mockImplementation((_env, { key }) =>
      Promise.resolve({
        key,
        createdAt: '2026-07-22T00:00:00.000Z',
        sizeBytes: 456,
      })
    );
  });

  it('rejects direct calls for another repository', async () => {
    await expect(
      runCiStep(
        fromPartial<Bindings>({}),
        cloudflareArtifacts({ owner: 'cloudflare', repo: 'example' }),
        { ...input, source: { ...input.source, repo: 'other' } }
      )
    ).rejects.toThrow(
      'Unsupported CI source: cloudflare-artifacts:cloudflare/other'
    );
  });

  it('returns inline logs and a workspace snapshot for uncached runs', async () => {
    mocks.run.mockResolvedValue(successfulRun('lineage-1'));
    const { adapter, succeed } = sourceControl();

    const result = await runCiStep(fromPartial<Bindings>({}), adapter, input);

    expect(result).toEqual({
      exitCode: 0,
      logs: { stdout: 'ok', stderr: '' },
      snapshot: { id: 'lineage-1', dir: '/workspace' },
      cachePointer: undefined,
    });
    expect(succeed).toHaveBeenCalledOnce();
    expect(mocks.publishSnapshotCache).not.toHaveBeenCalled();
  });

  it('injects deployment credentials without using the CI host account', async () => {
    mocks.run.mockResolvedValue(successfulRun('lineage-1'));
    const { adapter } = sourceControl();

    await runCiStep(
      fromPartial<Bindings>({
        CF_TOKEN: '[REDACTED]',
        CLOUDFLARE_ACCOUNT_ID: 'ci-host-account',
      }),
      adapter,
      {
        ...input,
        cloudflareCredentials: { accountId: 'deployment-account' },
      }
    );

    expect(mocks.run).toHaveBeenCalledWith(
      expect.objectContaining({
        extraEnv: {
          CLOUDFLARE_ACCOUNT_ID: 'deployment-account',
          CLOUDFLARE_API_TOKEN: '[REDACTED]',
        },
      })
    );
  });

  it('rejects malformed deployment credentials before starting a runner', async () => {
    const { adapter } = sourceControl();

    await expect(
      runCiStep(fromPartial<Bindings>({}), adapter, {
        ...input,
        cloudflareCredentials: 'invalid' as never,
      })
    ).rejects.toThrow(
      'runner(test): cloudflareCredentials must be true or contain an accountId'
    );
    expect(mocks.run).not.toHaveBeenCalled();
  });

  it('passes inherited lineage to the runner as a restore snapshot', async () => {
    mocks.run.mockResolvedValue(successfulRun('lineage-2'));
    const { adapter } = sourceControl();
    const snapshot = { id: 'lineage-1', dir: '/workspace' };

    await runCiStep(fromPartial<Bindings>({}), adapter, {
      ...input,
      snapshot,
    });

    expect(mocks.run).toHaveBeenCalledWith(
      expect.objectContaining({ restore: snapshot })
    );
  });

  it('configures workspace snapshot retention', async () => {
    mocks.run.mockResolvedValue(successfulRun('lineage-1'));
    const { adapter } = sourceControl();

    await runCiStep(fromPartial<Bindings>({}), adapter, {
      ...input,
      snapshotTtlSeconds: 86_400,
    });

    expect(mocks.run).toHaveBeenCalledWith(
      expect.objectContaining({ ttlSeconds: 86_400 })
    );
  });

  it('publishes and returns snapshot metadata when cache is configured', async () => {
    mocks.run.mockResolvedValue(successfulRun('cached-1'));
    const { adapter } = sourceControl();

    const result = await runCiStep(fromPartial<Bindings>({}), adapter, {
      ...input,
      cachePaths: ['pnpm-lock.yaml'],
    });

    expect(result.snapshot).toEqual({ id: 'cached-1', dir: '/workspace' });
    expect(result.cachePointer).toEqual({
      key: 'cache-key',
      createdAt: '2026-07-22T00:00:00.000Z',
      sizeBytes: 456,
    });
    expect(mocks.resolveCacheKey).toHaveBeenCalledWith({
      repo: 'cloudflare-artifacts:cloudflare/example:refs/heads/main',
      label: 'test',
      command: 'bun run test',
      cwd: undefined,
      env: undefined,
      paths: ['pnpm-lock.yaml'],
      blobs: [{ path: 'pnpm-lock.yaml', sha: 'blob-sha' }],
    });
    expect(mocks.publishSnapshotCache).toHaveBeenCalledWith(expect.anything(), {
      key: 'cache-key',
      label: 'test',
      snapshot: { id: 'cached-1', dir: '/workspace' },
      producedBySha: 'abc123',
    });
  });

  it('uses an explicit cache scope instead of its branch ref', async () => {
    mocks.run.mockResolvedValue(successfulRun('cached-1'));
    const { adapter } = sourceControl();

    await runCiStep(fromPartial<Bindings>({}), adapter, {
      ...input,
      cachePaths: ['pnpm-lock.yaml'],
      cacheScope: 'refs/cache/custom',
    });

    expect(mocks.resolveCacheKey).toHaveBeenCalledWith(
      expect.objectContaining({
        repo: 'cloudflare-artifacts:cloudflare/example:refs/cache/custom',
      })
    );
  });

  it('reuses a valid cached backup without starting a sandbox', async () => {
    mocks.lookupSnapshotCache.mockResolvedValue({
      status: 'hit',
      snapshot: { id: 'cached-1', dir: '/workspace' },
      cachePointer: {
        key: 'cache-key',
        createdAt: '2026-07-20T00:00:00.000Z',
        sizeBytes: 456,
      },
    });
    const { adapter } = sourceControl();

    const result = await runCiStep(fromPartial<Bindings>({}), adapter, {
      ...input,
      cachePaths: ['pnpm-lock.yaml'],
    });

    expect(result.snapshot).toEqual({ id: 'cached-1', dir: '/workspace' });
    expect(result.cachePointer?.key).toBe('cache-key');
    expect(result.logs).toEqual({
      stdout: 'cache hit: reusing cached-1',
      stderr: '',
    });
    expect(mocks.run).not.toHaveBeenCalled();
  });

  it('rejects empty cache inputs', async () => {
    const { adapter } = sourceControl();

    await expect(
      runCiStep(fromPartial<Bindings>({}), adapter, {
        ...input,
        cachePaths: [],
      })
    ).rejects.toThrow('cache(test): inputs must not be empty');
    expect(mocks.run).not.toHaveBeenCalled();
  });

  it('runs without caching when the source fingerprint is unavailable', async () => {
    mocks.run.mockResolvedValue(successfulRun('uncached-1'));
    const warning = vi.spyOn(console, 'warn').mockImplementation(() => {});
    const { adapter, provider } = sourceControl();
    vi.mocked(provider.listTreeBlobs).mockResolvedValue(null);

    const result = await runCiStep(fromPartial<Bindings>({}), adapter, {
      ...input,
      cachePaths: ['pnpm-lock.yaml'],
    });

    expect(result.cachePointer).toBeUndefined();
    expect(mocks.run).toHaveBeenCalledOnce();
    expect(mocks.resolveCacheKey).not.toHaveBeenCalled();
    expect(mocks.lookupSnapshotCache).not.toHaveBeenCalled();
    expect(mocks.publishSnapshotCache).not.toHaveBeenCalled();
    expect(warning).toHaveBeenCalledWith(
      '[cache] source fingerprint unavailable; skipping cache',
      {
        label: 'test',
        provider: 'cloudflare-artifacts',
        paths: ['pnpm-lock.yaml'],
      }
    );
  });

  it('throws failed commands and does not publish a backup', async () => {
    mocks.run.mockResolvedValue({
      exitCode: 1,
      logs: { stdout: '', stderr: 'failed' },
      preview: { stdout: '', stderr: 'failed' },
    });
    const { adapter, fail } = sourceControl();

    await expect(
      runCiStep(fromPartial<Bindings>({}), adapter, input)
    ).rejects.toThrow('test failed with exit code 1');
    expect(fail).toHaveBeenCalledOnce();
    expect(mocks.publishSnapshotCache).not.toHaveBeenCalled();
  });

  it('redacts injected values from failed command diagnostics', async () => {
    mocks.run.mockResolvedValue({
      exitCode: 1,
      logs: { stdout: '', stderr: 'token=[REDACTED]' },
      preview: { stdout: '', stderr: 'token=[REDACTED]' },
    });
    const { adapter, fail } = sourceControl();

    const failure = await runCiStep(fromPartial<Bindings>({}), adapter, {
      ...input,
      env: { API_TOKEN: '[REDACTED]' },
    }).catch((error) => error);

    expect(failure.message).toContain('token=[REDACTED]');
    expect(failure.message).not.toContain('super-secret-value');
